#include <cstdint>
#include <cstdio>
#include <cstring>
#include <vector>

std::uint32_t read32(const std::vector<std::uint8_t>& d, std::size_t at)
{
    std::uint32_t v{};
    std::memcpy(&v, d.data() + at, sizeof v);
    return v;
}

int main()
{
    std::vector<std::uint8_t> file(0x200);
    file[0] = 'M';
    file[1] = 'Z';
    std::printf("%c%c\n", file[0], file[1]);
}
